function renderCatalog(){const grid=$('#catalogGrid'),kind=$('#catalogKind').value,q=normalize($('#catalogSearch').value);const all=CATALOG.filter(v=>(kind==='all'||v.k===kind)&&(!q||[v.n,v.en,v.id,lookupItem(v.sig)?.n].some(t=>normalize(t).includes(q)))).sort((a,b)=>b.r-a.r||a.n.localeCompare(b.n,'ru'));grid.replaceChildren();for(const v of all.slice(0,catalogLimit)){const card=document.createElement('article');card.className='catalog-card';card.dataset.rank=String(v.r);const info=document.createElement('div'),title=document.createElement('h4');title.textContent=v.n;info.append(title);if(v.r){const stars=document.createElement('span');stars.className='stars';stars.textContent='★'.repeat(v.r);info.append(stars);}if(v.sig){const sig=lookupItem(v.sig);if(sig){const detail=document.createElement('small');detail.textContent='Сигнатура: '+sig.n;info.append(detail);}}if(v.k!=='weapons'){const btn=document.createElement('button');btn.className='ghost';btn.textContent=v.k==='characters'?'В коллекцию':'В план фарма';btn.onclick=()=>{if(v.k==='characters'){$('#characterName').value=v.n;navigate('profile');}else{$('#resourceName').value=v.n;navigate('resources');}};info.append(btn);}if(v.k==='characters'||v.k==='weapons'){const up=document.createElement('button');up.className='ghost';up.textContent='Рассчитать прокачку';up.onclick=()=>{navigate('upgrade');changeUpgradeKind(v.k,v.id);};info.append(up);}card.append(iconFor(v),info);grid.append(card);}$('#catalogCount').textContent='Найдено: '+all.length;$('#catalogMore').hidden=all.length<=catalogLimit;}
function initCatalog(){for(const [id,kind] of [['characterSuggestions','characters'],['resourceSuggestions','items'],['weaponSuggestions','weapons']]){const el=document.getElementById(id);for(const v of CATALOG.filter(x=>x.k===kind)){const opt=document.createElement('option');opt.value=v.n;el.append(opt);}}$('#catalogSearch').oninput=$('#catalogKind').onchange=()=>{catalogLimit=48;renderCatalog();};$('#catalogMore').onclick=()=>{catalogLimit+=48;renderCatalog();};renderCatalog();}

function extract(raw){
 const out=[],counts=new Map(),unknown=new Set();
 const aliases={'100':'100','200':'200','301':'301','302':'302','400':'301','500':'500',character:'301',character2:'301','character-event':'301','character-event-2':'301',weapon:'302','weapon-event':'302',standard:'200',permanent:'200',beginner:'100',beginners:'100',chronicled:'500','chronicled-wish':'500'};
 const norm=t=>aliases[String(t??'').toLowerCase()];
 function parse(v){if(typeof v==='string'&&/^\s*[\[{]/.test(v)){try{return JSON.parse(v);}catch{}}return v;}
 function add(x,t,uid,pm,index){
  const item=String(x.item_id??x.itemId??(pm?x.id:undefined)??x.name??x.item_name??x.itemName??x.item??'');
  const dict=ITEMS[item]??ITEMS[item.toLowerCase().replace(/[\s-]+/g,'_')];
  const weaponRank=/^1[1-5]([345])\d{2}$/.exec(item);
  const rank=Number(x.rank_type??x.rankType??x.rarity??x.rank??x.rare??dict?.[0]??weaponRank?.[1]??0);
  const time=String(x.time??x.timestamp??x.date??'');
  const type=norm(x.uigf_gacha_type??x.gacha_type??x.gachaType??x.banner_type??x.bannerType??x.code)??norm(t);
  if(!time||!type||!item)return;
  if(![3,4,5].includes(rank)){unknown.add(item);return;}
  const name=String(x.name??x.item_name??x.itemName??dict?.[1]??item.replace(/_/g,' '));
  const base=[uid,type,time,item,rank].join('|');const k=(counts.get(base)||0)+1;counts.set(base,k);
  const id=String(pm?(x.wish_id??x.gacha_id??'pm:'+base+'|'+k):(x.id??x.wish_id??base+'|'+k));
  out.push({id,rank,type,name,time,uid,item,order:pm?index:undefined});
 }
 const wrappers=new Set(['list','wishes','history','data','hk4e','accounts','result','wishHistory','pulls','wish','wish_history']);
 function visit(value,t,uid){
  const x=parse(value);if(!x||typeof x!=='object')return;
  if(Array.isArray(x)){x.forEach((v,i)=>visit(v,t,uid));return;}
  uid=String(x.uid??uid??'');
  if((x.time||x.timestamp||x.date)&&(x.item_id||x.itemId||x.name||x.item_name||x.itemName||x.item)){add(x,t,uid,false);return;}
  for(const [key,v] of Object.entries(x)){
   const match=/^(.*?)wish-counter-(beginners|character-event(?:-2)?|weapon-event|standard|chronicled(?:-wish)?)$/.exec(key);
   if(match){const block=parse(v);let account=parse(x[match[1]+'wish-uid']);if(account==null||typeof account==='object')account=uid;const list=Array.isArray(block)?block:parse(block?.pulls);if(Array.isArray(list))list.forEach((p,i)=>{if(p&&typeof p==='object')add(p,match[2],String(account??''),true,i);});continue;}
   if(wrappers.has(key)||norm(key))visit(v,norm(key)??t,uid);
  }
 }
 visit(raw,undefined,raw?.info?.uid);
 if(unknown.size)throw Error('Не удалось определить редкость '+unknown.size+' типов предметов: '+[...unknown].slice(0,5).join(', ')+'. Импорт остановлен, чтобы не исказить pity.');
 return out;
}
function sortWishes(a,b){try{const ai=BigInt(a.id),bi=BigInt(b.id);if(ai!==bi)return ai>bi?-1:1;}catch{}return String(b.time).localeCompare(String(a.time)) || (Number(b.order??0)-Number(a.order??0));}
function wishesFor(t){return state.wishes.filter(w=>t==='all'||typeOf(w.type)===t).sort(sortWishes);}
function pity(t){const rows=wishesFor(t);if(!rows.length)return null;let n=0;for(const w of rows){if(w.rank===5)return n;n++;}return n;}
function write(id,v){$(id).textContent=v;}

