function dashDate(s){const x=String(s||'').slice(0,10);return /^\d{4}-\d{2}-\d{2}$/.test(x)?x.split('-').reverse().join('.'):'Дата неизвестна';}
function dashRecords(all){const groups=new Map(),result=[];for(const w of all){const t=dashType(w.type).id;if(!groups.has(t))groups.set(t,[]);groups.get(t).push(w);}for(const [t,rows] of groups){let seen=false,n=0;for(const w of rows.slice().reverse()){n++;if(Number(w.rank)===5){result.push({w,t,p:seen?n:null,observed:n});seen=true;n=0;}}}return result.sort((a,b)=>sortWishes(a.w,b.w));}
function dashHitType(w){const day=String(w.time||'').slice(0,10),v=lookupWish(w);if(!v||!day.match(/^\d{4}-\d{2}-\d{2}$/))return null;const current=dashSchedule.filter(b=>b.type==='301'&&day>b.start.slice(0,10)&&day<b.end.slice(0,10));if(!current.length)return null;return current.some(b=>b.featured.includes(v.id))?'featured':'off';}
function dashRate(records){let prior=null,win=0,loss=0;for(const rec of records.filter(x=>x.t==='301').slice().reverse()){const status=dashHitType(rec.w);if(prior==='featured'&&status){if(status==='featured')win++;else loss++;}prior=status;}return {win,loss,n:win+loss};}
