function renderDashboard(all=wishesFor('all')){const total=all.length,records=dashRecords(all);dashIntervals=records;const five=records.length,known=records.filter(x=>x.p!==null&&x.p>0);const rates=dashRate(records);
const period=all.length?dashDate(all.at(-1).time)+' — '+dashDate(all[0].time):'Импортируй историю';write('#dashPeriod',period);write('#dashRarity',fmt(all.filter(w=>Number(w.rank)===4).length)+' выпадений 4★');write('#dashDonutTotal',fmt(total));const nickname=String(state.nickname||'').trim();write('#dashWelcome',nickname?'Путешественник '+nickname+' · твоя личная хроника Тейвата.':'Твоя личная хроника путешествий по Тейвату.');
const legend=$('#dashLegend');legend.replaceChildren();const banners=$('#dashBannerCards');banners.replaceChildren();let pos=0;const stops=[];
for(const d of DASH_TYPES){const rows=all.filter(w=>dashType(w.type).id===d.id),count=rows.length,stars=rows.filter(w=>Number(w.rank)===5),share=total?count/total*100:0;if(d.id==='other'&&!count)continue;if(share){stops.push(d.color+' '+pos+'% '+(pos+share)+'%');pos+=share;}const line=dashNode('button','dash-legend-row');line.type='button';const dot=dashNode('i','dash-dot');dot.style.background=d.color;line.append(dot,dashNode('span','',d.short),dashNode('strong','',fmt(count)),dashNode('small','',share.toLocaleString('ru-RU',{maximumFractionDigits:1})+'%'));line.onclick=()=>{navigate('wishes');$('#bannerFilter').value=d.id==='other'?'all':d.id;historyRank='all';$('#historySearch').value='';resetHistory();};legend.append(line);
if(!count&&['100','500','other'].includes(d.id))continue;const card=dashNode('article','dash-banner-card');card.style.setProperty('--banner-color',d.color);const head=dashNode('div','dash-banner-head');head.append(dashNode('span','dash-banner-symbol',d.symbol),dashNode('h3','',d.label));card.append(head);const numbers=dashNode('div','dash-banner-numbers');const big=dashNode('div');big.append(dashNode('strong','',fmt(count)),dashNode('small','','молитв'));const tiny=dashNode('div');tiny.append(dashNode('strong','',fmt(stars.length)),dashNode('small','','5★'));numbers.append(big,tiny);card.append(numbers);
if(d.cap){const p=rows.length?pity(d.id):null;const exact=stars.length>0;const meter=dashNode('div','dash-pity-label');meter.append(dashNode('span','','Счётчик 5★'),dashNode('b','',p===null?'— / '+d.cap:(exact?'':'≥ ')+p+' / '+d.cap));const bar=dashNode('div','dash-pity-track'),fill=dashNode('i');fill.style.width=Math.min(100,(p||0)/d.cap*100)+'%';bar.append(fill);card.append(meter,bar,dashNode('p','dash-pity-note',p===null?'Нет истории':!exact?'Нет предыдущего 5★ в импорте':p<d.cap?'До предельного pity: '+(d.cap-p):'Проверь полноту истории'));}
const last=stars[0],lastWrap=dashNode('div','dash-last');lastWrap.append(dashNode('small','','Последнее 5★'));if(last){const rec=records.find(x=>x.w===last);lastWrap.append(itemLabel(lookupWish(last),last.name,(rec?.p==null?'Pity неизвестен':rec.p+' молитв')+' · '+dashDate(last.time),5));}else lastWrap.append(dashNode('p','hint','Пока нет выпадений'));card.append(lastWrap);const more=dashNode('button','ghost dash-more','История баннера →');more.onclick=line.onclick;card.append(more);banners.append(card);}
$('#dashDonut').style.background=total?'conic-gradient('+stops.join(',')+')':'#362b47';$('#dashDonut').setAttribute('aria-label',total?'Распределение '+total+' молитв по баннерам':'Нет импортированных молитв');
const luck=$('#dashLuck');luck.replaceChildren();const avg=known.length?(known.reduce((n,r)=>n+r.p,0)/known.length).toLocaleString('ru-RU',{maximumFractionDigits:1}):'—';dashMetric(luck,'Средний pity',avg,known.length+' полных интервалов');dashMetric(luck,'Самое раннее',known.length?Math.min(...known.map(x=>x.p)):'—','молитв до 5★');dashMetric(luck,'Самое позднее',known.length?Math.max(...known.map(x=>x.p)):'—','молитв до 5★');dashMetric(luck,'Победы в 50/50 (оценка)',rates.n?Math.round(100*rates.win/rates.n)+'%':'—',rates.n?rates.win+' побед / '+rates.loss+' проигрышей':'Недостаточно данных');dashMetric(luck,'5★ персонажей',fmt(records.filter(x=>lookupWish(x.w)?.k==='characters').length),'распознано по базе');dashMetric(luck,'5★ оружия',fmt(records.filter(x=>lookupWish(x.w)?.k==='weapons').length),'распознано по базе');
write('#dashLuckNote','Pity: только интервалы между двумя 5★ одной категории. Оценка 50/50: только распознанные ивентовые выпадения после предыдущего ивентового 5★; гарантированные и неоднозначные случаи исключены. Сияние пленённого света отдельно не определяется.');
const recent=$('#recentFive');recent.replaceChildren();if(!records.length)recent.append(dashNode('p','hint','Импортируй историю, чтобы здесь появилась коллекция твоих 5★.'));for(const r of records.slice(0,8)){const v=lookupWish(r.w),card=dashNode('article','dash-five-card');card.dataset.rank='5';card.style.setProperty('--banner-color',rarityStyle(5));const head=dashNode('div','dash-five-art');head.append(iconFor(v,5),dashNode('span','dash-five-pill',r.p===null?'?':r.p+' крут.'));const info=dashNode('div','dash-five-info');info.append(dashNode('strong','',dashName(r.w)),dashNode('span','gold','★★★★★'),dashNode('small','',dashType(r.t).short+' · '+dashDate(r.w.time)));card.append(head,info);recent.append(card);}
renderDashChart();}
function renderDashChart(){const wrap=$('#dashChart'),filter=$('#dashHistoryType').value;const values=dashIntervals.filter(x=>filter==='all'||x.t===filter).slice(0,20).reverse();wrap.replaceChildren();if(!values.length){wrap.append(dashNode('p','hint dash-chart-empty','Нет пятизвёздочных выпадений для выбранной категории.'));return;}const max=Math.max(90,...values.map(r=>r.p||0)),plot=dashNode('div','dash-chart-plot');for(const val of [max,Math.round(max/2),0]){const grid=dashNode('div','dash-chart-line');grid.style.bottom=(val/max*100)+'%';grid.append(dashNode('span','',val));plot.append(grid);}const cols=dashNode('div','dash-chart-cols');for(const r of values){const el=dashNode('div','dash-chart-col');el.style.setProperty('--banner-color',dashType(r.t).color);const track=dashNode('div','dash-chart-track'),bar=dashNode('div','dash-chart-bar'+(r.p===null?' unknown':''));bar.style.height=(r.p===null?8:Math.max(2,r.p/max*100))+'%';bar.append(dashNode('span','',r.p===null?'?':r.p));track.append(bar);const label=dashNode('div','dash-chart-label');label.append(iconFor(lookupWish(r.w),5),dashNode('small','',dashName(r.w)));el.title=dashName(r.w)+' · '+dashType(r.t).short+' · '+(r.p===null?'Pity неизвестен':r.p+' молитв')+' · '+dashDate(r.w.time);el.tabIndex=0;el.setAttribute('aria-label',el.title);el.append(track,label);cols.append(el);}plot.append(cols);wrap.append(plot);}
function dashServerDate(){const offsets={eu:1,usa:-5,os:8,cn:8};const offset=offsets[state.server]??1;return new Date(Date.now()+offset*3600000).toISOString().replace('T',' ').slice(0,19);}
function renderDashCurrent(){const box=$('#dashCurrent');box.replaceChildren();const now=dashServerDate(),day=now.slice(0,10);const active=dashSchedule.filter(b=>['301','302','500'].includes(b.type)&&b.start<=now&&b.end>=now);for(const b of active){const d=dashType(b.type),card=dashNode('article','dash-live-card');card.style.setProperty('--banner-color',d.color);card.append(dashNode('span','eyebrow',d.label),dashNode('h4','',b.type==='302'?'Воплощение божества':b.type==='500'?'Молитва хроник':b.featured.map(dashItemName).join(' / ')));const art=dashNode('div','dash-live-art');for(const id of b.featured){const v=lookupItem(id),cell=dashNode('div','dash-live-item');cell.append(iconFor(v,5),dashNode('small','',dashItemName(id)));art.append(cell);}card.append(art);const days=Math.max(0,Math.ceil((Date.parse(b.end.replace(' ','T')+'Z')-Date.parse(now.replace(' ','T')+'Z'))/86400000));card.append(dashNode('small','dash-live-date',dashDate(b.start)+' — '+dashDate(b.end)+' · ≈ '+days+' дн.'));box.append(card);}
const st=dashNode('article','dash-live-card standard');st.style.setProperty('--banner-color','#76bbeb');st.append(dashNode('span','eyebrow','ПОСТОЯННАЯ МОЛИТВА'),dashNode('h4','','Жажда странствий'));const art=dashNode('div','dash-live-art');for(const id of ['mona','diluc','jean','qiqi','keqing']){const v=lookupItem(id);if(v)art.append(iconFor(v,5));}st.append(art,dashNode('small','dash-live-date','Без ограничения по времени · иллюстрация пула'));box.append(st);
if(!active.length){const p=dashNode('p','hint','В доступном расписании нет подтверждённых активных ивентовых баннеров на '+dashDate(day)+'. Сверь календарь или игру.');box.prepend(p);}write('#dashScheduleNote','Источник расписания: Paimon.moe · '+(dashScheduleLive?'обновлено из открытой базы':'локальный снимок базы')+' · время сервера приблизительное; актуальность сверяй в игре.');}
function parseDashSchedule(source){const out=[];let type;for(const match of source.matchAll(/^  (beginners|standard|characters|weapons|chronicled): \[|^    \{([\s\S]*?)^    \},?/gm)){if(match[1]){type=({beginners:'100',standard:'200',characters:'301',weapons:'302',chronicled:'500'})[match[1]];continue;}const s=match[2];if(!type||!s)continue;const prop=k=>s.match(new RegExp("\\b"+k+"\\s*:\\s*(['\"])(.*?)\\1"))?.[2];const arr=s.match(/\bfeatured\s*:\s*\[([\s\S]*?)\]/)?.[1]||'';const featured=[...arr.matchAll(/['"]([^'"]+)['"]/g)].map(m=>m[1]);const start=prop('start'),end=prop('end');if(!start||!end)continue;out.push({type,name:prop('name'),start,end,featured,version:prop('version')||'',zone:/timezoneDependent:\s*true/.test(s)});}return out;}
async function refreshDashSchedule(){try{const r=await fetch('https://raw.githubusercontent.com/MadeBaruna/paimon-moe/main/src/data/banners.js',{cache:'no-cache',credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)return;const src=await r.text();if(src.length>1000000)return;const data=parseDashSchedule(src);if(data.length<100||!data.some(x=>x.type==='302'))return;const latest=x=>x.filter(b=>['301','302','500'].includes(b.type)).map(b=>b.end).sort().at(-1)||'';if(latest(data)<latest(dashSchedule))return;dashSchedule=data;dashScheduleLive=true;renderDashCurrent();renderDashboard();}catch{}}
function renderDashGoal(now,total,worst,ww){const include=!!state.goalIncludeWeapon,need=worst+(include?ww:0),missing=Math.max(0,need-total);write('#dashGuarantee',state.guarantee?'Гарант персонажа: да (вручную)':'Гарант персонажа: не отмечен');write('#dashProjected','К сроку: '+fmt(total)+' молитв');const box=$('#dashGoalView');box.replaceChildren();const char=lookupItem(state.goalCharacter),weapon=lookupItem(state.weaponWishName);const targets=dashNode('div','dash-goal-targets');targets.append(itemLabel(char,state.goalCharacter||'Персонаж не выбран','C'+(Math.max(1,num(state.copies))-1),5));if(include)targets.append(itemLabel(weapon,state.weaponWishName||'Оружие не выбрано','R'+Math.max(1,num(state.weaponCopies)),5));box.append(targets);const metrics=dashNode('div','dash-goal-numbers');dashMetric(metrics,'Сейчас',fmt(now),'молитв');dashMetric(metrics,'К сроку',fmt(total),'молитв');dashMetric(metrics,'До полной гарантии',fmt(need),'максимум');dashMetric(metrics,'Не хватает',fmt(missing),'к сроку');box.append(metrics);$('#dashGoalBar').style.width=Math.min(100,total/Math.max(need,1)*100)+'%';write('#dashGoalText',Math.round(Math.min(100,total/Math.max(need,1)*100))+'% от консервативной цели · настройки pity, сроков и гаранта берутся из калькулятора.');}
function initDashboard(){$('#dashHistoryType').addEventListener('change',renderDashChart);renderDashCurrent();refreshDashSchedule();}


let historyRank='all',historyMode='cards',historyPage=0;const HISTORY_PAGE_SIZE=60;
function cleanGameName(name){return String(name??'').replace(/^\s*#/,'').replace(/\{SPACE\}/gi,' ').replace(/\s+/g,' ').trim();}
const rarityStyle=r=>r===5?'#e8bd77':r===4?'#b48ae7':'#78a9d6';
function historyRecords(all){const groups=new Map(),result=[];for(const w of all){const t=typeOf(w.type);if(!groups.has(t))groups.set(t,[]);groups.get(t).push(w);}for(const [t,rows] of groups){let seen5=false,seen4=false,n5=0,n4=0,ordinal=0;for(const w of rows.slice().reverse()){ordinal++;n5++;n4++;const rank=Number(w.rank);let p=null;if(rank===5){p=seen5?n5:null;seen5=true;n5=0;}else if(rank===4){p=seen4?n4:null;seen4=true;n4=0;}result.push({w,t,rank,p,ordinal});}}return result.sort((a,b)=>sortWishes(a.w,b.w));}
function historyPill(r){return r.rank===3?'№ '+fmt(r.ordinal):r.p===null?'?':fmt(r.p)+' крут.';}
function makeHistoryCard(r){const w=r.w,v=lookupWish(w),card=dashNode('article','history-card dash-five-card');card.dataset.rank=String(r.rank);card.style.setProperty('--banner-color',rarityStyle(r.rank));const art=dashNode('div','dash-five-art');const pill=dashNode('span','dash-five-pill',historyPill(r));pill.title=r.rank===3?'Номер в импортированной истории':r.p===null?'Начало интервала неизвестно':'Молитв до выпадения '+r.rank+'★';art.append(iconFor(v,r.rank),pill);const info=dashNode('div','dash-five-info');info.append(dashNode('strong','',cleanGameName(v?.n||w.name)),dashNode('span','history-stars','★'.repeat(Math.max(0,Math.min(5,r.rank)))),dashNode('small','history-banner',dashType(r.t).short),dashNode('small','',dashDate(w.time)));card.append(art,info);return card;}
function renderHistory(){const all=historyRecords(wishesFor('all')),type=$('#bannerFilter').value,q=normalize($('#historySearch').value),sort=$('#historySort').value;const records=all.filter(r=>(type==='all'||r.t===type)&&(historyRank==='all'||(historyRank==='45'?r.rank>=4:String(r.rank)===historyRank))&&(!q||[r.w.name,lookupWish(r.w)?.n,lookupWish(r.w)?.en,r.w.item].some(n=>normalize(n).includes(q))));if(sort==='old')records.reverse();if(sort==='rarity')records.sort((a,b)=>b.rank-a.rank||sortWishes(a.w,b.w));const pages=Math.max(1,Math.ceil(records.length/HISTORY_PAGE_SIZE));historyPage=Math.min(Math.max(0,historyPage),pages-1);const visible=records.slice(historyPage*HISTORY_PAGE_SIZE,(historyPage+1)*HISTORY_PAGE_SIZE);
const gallery=$('#historyGallery'),table=$('#wishRows');gallery.replaceChildren();table.replaceChildren();gallery.hidden=historyMode!=='cards';$('#historyTableWrap').hidden=historyMode!=='table';if(historyMode==='cards'){for(const r of visible)gallery.append(makeHistoryCard(r));if(!visible.length)gallery.append(dashNode('p','hint history-empty',all.length?'По выбранным фильтрам ничего не найдено.':'История пока пуста. Импортируй JSON, чтобы увидеть выпадения.'));}else{for(const r of visible){const tr=document.createElement('tr');const w=r.w;for(const [i,value] of [dashDate(w.time),w.name,'★'.repeat(r.rank),dashType(r.t).short,historyPill(r)].entries()){const td=document.createElement('td');if(i===1)td.append(itemLabel(lookupWish(w),cleanGameName(w.name),'',r.rank));else td.textContent=value;if(i===2||i===4)td.style.color=rarityStyle(r.rank);tr.append(td);}table.append(tr);}if(!visible.length){const tr=document.createElement('tr'),td=document.createElement('td');td.colSpan=5;td.textContent='Нет записей';tr.append(td);table.append(tr);}}
write('#historyCount','Найдено '+fmt(records.length)+' из '+fmt(all.length)+' · '+(records.length?fmt(historyPage*HISTORY_PAGE_SIZE+1)+'–'+fmt(historyPage*HISTORY_PAGE_SIZE+visible.length):'0'));write('#historyPage',(historyPage+1)+' / '+pages);$('#historyPrev').disabled=historyPage===0;$('#historyNext').disabled=historyPage>=pages-1;$('[data-history-rank]').forEach(b=>{const yes=b.dataset.historyRank===historyRank;b.classList.toggle('active',yes);b.setAttribute('aria-pressed',String(yes));});$('#historyCardView').classList.toggle('active',historyMode==='cards');$('#historyTableView').classList.toggle('active',historyMode==='table');}
function resetHistory(){historyPage=0;renderHistory();}
function initHistory(){for(const b of $('[data-history-rank]'))b.onclick=()=>{historyRank=b.dataset.historyRank;resetHistory();};$('#historySearch').oninput=resetHistory;$('#historySort').onchange=resetHistory;$('#bannerFilter').onchange=resetHistory;$('#historyCardView').onclick=()=>{historyMode='cards';renderHistory();};$('#historyTableView').onclick=()=>{historyMode='table';renderHistory();};$('#historyPrev').onclick=()=>{historyPage--;renderHistory();};$('#historyNext').onclick=()=>{historyPage++;renderHistory();};}
function migrateGameNames(){let changed=false;for(const r of state.resources){const name=String(r.name||''),v=lookupItem(r.itemId)||lookupItem(cleanGameName(name));const next=v?.k==='items'?v.n:cleanGameName(name);if(next&&name!==next){r.name=next;changed=true;}}if(changed)save();}

function renderWishes(){const all=wishesFor('all');write('#statTotal',fmt(all.length));write('#statFive',fmt(all.filter(w=>w.rank===5).length));write('#statPity',pity('301')===null?'—':(all.some(w=>typeOf(w.type)==='301'&&Number(w.rank)===5)?'':'≥ ')+pity('301'));renderDashboard(all);
const box=$('#bannerStats');box.replaceChildren();for(const t of ['301','302','200','500']){if(t==='500'&&!wishesFor(t).length)continue;const e=document.createElement('article');e.className='stat';const a=document.createElement('span'),b=document.createElement('b');a.textContent=banner(t)+' · '+wishesFor(t).length+' молитв';b.textContent=(pity(t)??'—')+' pity';e.append(a,b);box.append(e);}
renderHistory();}
function renderCalc(){const gems=num(state.primos),fates=num(state.fates),income=num(state.days)*num(state.daily)+num(state.extra),now=Math.floor(gems/160)+fates,total=Math.floor((gems+income)/160)+fates;const hist=state.useHistory?pity('301'):null,p=Math.min(89,num(hist??state.manualPity)),copies=Math.max(1,Math.min(7,num(state.copies))),worst=90-p+(copies*2-1-(state.guarantee?1:0))*90,missing=Math.max(0,worst-total);write('#statPulls',fmt(now));write('#calcNow',fmt(now));write('#calcTotal',fmt(total));write('#calcWorst',fmt(worst));write('#calcMissing',fmt(missing));write('#calcGems',fmt(Math.max(0,(worst-fates)*160-gems-income)));$('#calcBar').style.width=Math.min(100,total/worst*100)+'%';const wp=Math.min(79,num(state.weaponHistory?pity('302')??state.weaponPity:state.weaponPity)),wc=Math.max(1,Math.min(5,num(state.weaponCopies))),ww=80-wp+(wc*2-1-(state.weaponPoint?1:0))*80;write('#weaponWorst',fmt(ww));write('#weaponMissing',fmt(Math.max(0,ww-total)));write('#weaponGems',fmt(Math.max(0,(ww-fates)*160-gems-income)));write('#combinedWorst',fmt(worst+ww));write('#combinedMissing',fmt(Math.max(0,worst+ww-total)));renderDashGoal(now,total,worst,ww);write('#calcText',missing?'До полного гаранта пока не хватает круток.':'Накоплений хватает даже для худшего сценария!');}
function row(list,title,detail,remove){const el=document.createElement('div'),info=document.createElement('div'),strong=document.createElement('strong'),small=document.createElement('small'),btn=document.createElement('button');el.className='item';strong.textContent=title;small.textContent=detail;btn.textContent='Удалить';btn.onclick=remove;const v=lookupItem(title);if(v){el.append(itemLabel(v,title,detail,v.r),btn);}else{info.append(strong,small);el.append(info,btn);}list.append(el);}
function renderProfile(){const list=$('#characterList');list.replaceChildren();state.characters.forEach((c,i)=>row(list,c.name,'Уровень '+c.level,()=>{state.characters.splice(i,1);save();renderProfile();}));const uid=String(state.uid||'').trim();$('#enkaLink').href=/^\d{9,10}$/.test(uid)?'https://enka.network/u/'+uid+'/':'https://enka.network/';}
function renderResources(){const list=$('#resourceList');list.replaceChildren();if(!state.resources.length)list.textContent='Пока нет целей.';state.resources.forEach((r,i)=>row(list,r.name,'Есть '+fmt(r.have)+' / Нужно '+fmt(r.need)+' · Осталось '+fmt(Math.max(0,r.need-r.have)),()=>{state.resources.splice(i,1);save();renderResources();}));write('#resinResult',fmt(num($('#resinRuns').value)*num($('#resinCost').value)));}
function render(){renderWishes();renderCalc();renderProfile();renderResources();}
const titles={overview:'Обзор аккаунта',wishes:'История молитв',calculator:'Калькулятор круток',profile:'Профиль путешественника',resources:'Планировщик ресурсов',upgrade:'Мастерская возвышения',map:'Карта Тейвата',catalog:'Архив Тейвата',settings:'Настройки и данные'};
function navigate(tab){$$('.page').forEach(e=>e.classList.toggle('active',e.id===tab));$$('[data-tab]').forEach(e=>e.classList.toggle('active',e.dataset.tab===tab));write('#pageTitle',titles[tab]||titles.overview);if(tab==='catalog')renderCatalog();if(tab==='wishes')renderHistory();window.scrollTo({top:0,behavior:'smooth'});}
$$('[data-tab]').forEach(b=>b.onclick=()=>navigate(b.dataset.tab));$$('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));
$$('[data-field]').forEach(el=>{const k=el.dataset.field;el.type==='checkbox'?el.checked=Boolean(state[k]):el.value=state[k]??'';el.addEventListener('input',()=>{state[k]=el.type==='checkbox'?el.checked:el.type==='number'?num(el.value):el.value;save();renderCalc();if(k==='uid')renderProfile();if(k==='nickname')renderDashboard();if(k==='server')renderDashCurrent();if(k==='weaponWishName')$('[data-field="weaponWishName"]').forEach(other=>{if(other!==el)other.value=el.value;});});});
$('#bannerFilter').onchange=resetHistory;
$('#wishFile').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>40*1024*1024)throw Error('Файл больше 40 МБ.');let incoming=extract(JSON.parse((await f.text()).replace(/^\uFEFF/,'')));if(!incoming.length)throw Error('Не найдены записи молитв. Проверь формат JSON.');const ids=[...new Set(incoming.map(w=>w.uid).filter(Boolean))];if(ids.length){let selected=String(state.uid||'').trim();if(selected&&!ids.includes(selected))throw Error('UID файла отличается от UID профиля.');if(!selected&&ids.length>1){selected=String(prompt('В файле несколько аккаунтов. Введи нужный UID: '+ids.join(', '),'')||'').trim();if(!ids.includes(selected))throw Error('Аккаунт не выбран.');}if(!selected)selected=ids[0];incoming=incoming.filter(w=>!w.uid||w.uid===selected);if(!state.uid){state.uid=selected;$('[data-field="uid"]').value=state.uid;}}const map=new Map(state.wishes.map(w=>[typeOf(w.type)+':'+w.id,w]));const before=map.size;incoming.forEach(w=>map.set(w.type+':'+w.id,w));state.wishes=[...map.values()].sort(sortWishes);save();render();notice('Импортировано '+incoming.length+' записей, новых: '+(map.size-before)+'.');}catch(err){notice('Ошибка импорта: '+err.message);}finally{e.target.value='';}};
$('#addCharacter').onclick=()=>{const name=$('#characterName').value.trim();if(!name)return notice('Введи имя персонажа.');state.characters.push({name,level:Math.min(90,Math.max(1,num($('#characterLevel').value)))});$('#characterName').value='';save();renderProfile();};
$('#addResource').onclick=()=>{const name=$('#resourceName').value.trim();if(!name)return notice('Введи название материала.');state.resources.push({name,need:Math.max(1,num($('#resourceNeed').value)),have:num($('#resourceHave').value)});$('#resourceName').value='';save();renderResources();};
$('#resinRuns').oninput=renderResources;$('#resinCost').onchange=renderResources;
$('#enkaBtn').onclick=async()=>{const uid=String(state.uid||'').trim();if(!/^\d{9,10}$/.test(uid))return notice('Введи корректный UID (9–10 цифр).');const out=$('#enkaOutput');out.textContent='Пробуем получить публичную витрину…';const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),8000);try{const r=await fetch('https://enka.network/api/uid/'+uid+'/',{signal:ctrl.signal});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json(),p=d.playerInfo||{};out.textContent='Имя: '+(p.nickname||'не указано')+' · Уровень приключений: '+(p.level??'—')+' · Персонажей в витрине: '+(d.avatarInfoList?.length??0)+'. Полный инвентарь по UID недоступен.';if(p.nickname&&!state.nickname){state.nickname=p.nickname;$('[data-field="nickname"]').value=p.nickname;save();}}catch{out.textContent='Автоматическая загрузка недоступна (CORS, сеть или ограничения Enka). Открой профиль по ссылке и добавь персонажей вручную.';}finally{clearTimeout(timer);}};
function download(obj,name){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
$('#backupBtn').onclick=()=>download({app:'noctis-genshin-planner',version:1,exportedAt:new Date().toISOString(),data:state},'noctis-backup.json');
$('#restoreFile').onchange=async e=>{try{const f=e.target.files?.[0];if(!f)return;const x=JSON.parse(await f.text());if(x.app!=='noctis-genshin-planner'||!x.data||!Array.isArray(x.data.wishes)||!Array.isArray(x.data.resources)||!Array.isArray(x.data.characters))throw Error('Неверный формат резервной копии.');if(!confirm('Заменить все текущие данные резервной копией?'))return;state={...defaults(),...x.data};save();location.reload();}catch(err){notice('Не удалось восстановить копию: '+err.message);}finally{e.target.value='';}};
$('#clearBtn').onclick=()=>{if(confirm('Точно удалить все локальные данные? Это действие нельзя отменить без резервной копии.')){localStorage.removeItem(KEY);location.reload();}};

const UP=window.NOCTIS_UPGRADES||{upgrades:{characters:{},weapons:{}},characterXP:[],weaponXP:[],talent:[]};
let calculatedMaterials={};

let upgradeLimit=30;
function upgradeEntries(){const kind=$('#upKind').value,q=normalize($('#upSearch').value),rarity=$('#upRarity').value,group=UP.upgrades[kind]||{};return Object.keys(group).map(id=>({id,v:CATALOG.find(x=>x.k===kind&&x.id===id)||lookupItem(id),entry:group[id]})).filter(x=>(rarity==='all'||String(x.entry.r)===rarity)&&(!q||[x.id,x.v?.n,x.v?.en,lookupItem(x.v?.sig)?.n].some(v=>normalize(v).includes(q)))).sort((a,b)=>b.entry.r-a.entry.r||(a.v?.n||a.id).localeCompare(b.v?.n||b.id,'ru'));}
function changeUpgradeKind(kind,preferred){$('#upKind').value=kind;$('#upSearch').value='';$('#upRarity').value='all';upgradeLimit=30;fillUpgrade(preferred);}
function fillUpgrade(preferred){const kind=$('#upKind').value,sel=$('#upItem'),group=UP.upgrades[kind]||{},prev=preferred||sel.value;sel.replaceChildren();for(const id of Object.keys(group)){const opt=document.createElement('option');opt.value=id;opt.textContent=lookupItem(id)?.n||id;sel.append(opt);}sel.value=Object.hasOwn(group,prev)?prev:'';$$('[data-up-kind]').forEach(b=>{const active=b.dataset.upKind===kind;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});$('#upTalent').hidden=kind!=='characters';renderUpgradeMatches();renderUpgradeSelected();calcUpgrade();}
function selectUpgrade(id){const sel=$('#upItem');if(!Object.hasOwn(UP.upgrades[$('#upKind').value]||{},id))return;sel.value=id;const e=UP.upgrades[$('#upKind').value][id];const max=e.stages.length<6?([20,40,50,60,70,80][e.stages.length]||90):90;for(const key of ['upFrom','upTo']){const el=$('#'+key);if(Number(el.value)>max)el.value=String(max);}renderUpgradeMatches();renderUpgradeSelected();calcUpgrade();}
function renderUpgradeMatches(){const list=$('#upMatches'),entries=upgradeEntries();list.replaceChildren();$('#upCount').textContent=fmt(entries.length)+' найдено';$('#upMore').hidden=entries.length<=upgradeLimit;if(!entries.length){const p=document.createElement('p');p.className='hint up-empty';p.textContent='Ничего не найдено. Попробуй другое имя или сними фильтр редкости.';list.append(p);return;}for(const x of entries.slice(0,upgradeLimit)){const b=document.createElement('button');b.type='button';b.className='up-choice'+(x.id===$('#upItem').value?' selected':'');b.setAttribute('aria-pressed',String(x.id===$('#upItem').value));const info=document.createElement('span'),n=document.createElement('strong'),stars=document.createElement('small');n.textContent=x.v?.n||x.id;stars.textContent='★'.repeat(x.entry.r);info.append(n,stars);b.append(iconFor(x.v,x.entry.r),info);b.onclick=()=>selectUpgrade(x.id);list.append(b);}}
function renderUpgradeSelected(){const el=$('#upSelected'),kind=$('#upKind').value,id=$('#upItem').value,entry=UP.upgrades[kind]?.[id];el.replaceChildren();if(!entry){el.textContent='Выбери персонажа или оружие слева.';return;}const v=CATALOG.find(x=>x.k===kind&&x.id===id)||lookupItem(id),info=document.createElement('div'),tag=document.createElement('div'),name=document.createElement('h4'),stars=document.createElement('div');tag.className='eyebrow';tag.textContent=kind==='characters'?'ПЕРСОНАЖ':'ОРУЖИЕ';name.textContent=v?.n||id;stars.className='gold';stars.textContent='★'.repeat(entry.r);info.append(tag,name,stars);if(v?.sig){const sig=lookupItem(v.sig);if(sig&&UP.upgrades.weapons[sig.id]){const b=document.createElement('button');b.className='ghost sig-link';b.type='button';b.textContent='⚔ '+sig.n+' →';b.onclick=()=>changeUpgradeKind('weapons',sig.id);info.append(b);}}el.append(iconFor(v,entry.r),info);}

function calcUpgrade(){const kind=$('#upKind').value,id=$('#upItem').value,entry=UP.upgrades[kind]?.[id],out=$('#upResults'),warning=$('#upWarning');out.replaceChildren();calculatedMaterials={};const from=num($('#upFrom').value),to=num($('#upTo').value);const caps=[20,40,50,60,70,80];const stage=(l,asc)=>caps.filter(x=>l>x||(asc&&l===x)).length;let messages=[];let invalid=false;const fail=m=>{warning.textContent=m;$('#upSummary').textContent='';$('#upAdd').disabled=true;$('#upCopy').disabled=true;};if(!entry)return fail('Выбери персонажа или оружие из базы.');const max=entry.stages.length<6?([20,40,50,60,70,80][entry.stages.length]||90):90;if(from<1||to<from||to>max)return fail('Уровни должны быть от 1 до '+max+', цель не ниже текущего.');const start=stage(from,$('#upFromAsc').checked),end=stage(to,$('#upToAsc').checked);if(start>end||end>entry.stages.length)return fail('Проверь отметки возвышения и предел уровня.');const add=(k,n)=>{if(k&&n>0)calculatedMaterials[k]=(calculatedMaterials[k]||0)+n;};for(const st of entry.stages.slice(start,end)){for(const [k,n] of st.items)add(k,n);add('mora',st.mora);}const xp=kind==='characters'?UP.characterXP:UP.weaponXP[entry.r-3];if(xp&&xp[to-1]!=null){const exp=xp[to-1]-xp[from-1];if(kind==='characters'){add('heros_wit',Math.ceil(exp/20000));add('mora',Math.ceil(exp/5));}else{add('mystic_enhancement_ore',Math.ceil(exp/10000));add('mora',Math.ceil(exp/10));}messages.push('Необходимо '+fmt(exp)+' опыта.');}else if(to>from)messages.push('Таблица опыта для этой редкости отсутствует; материалы возвышения рассчитаны отдельно.');
if(kind==='characters'){for(let i=0;i<3;i++){const f=num($('#talFrom'+i).value),t=num($('#talTo'+i).value);if(f<1||t<f||t>10)return fail('Уровни талантов должны быть от 1 до 10, цель не ниже текущего.');if(t>f&&(!entry.books||!entry.common||!entry.boss))return fail('Для этого персонажа в базе нет полной таблицы талантов. Установи одинаковые уровни талантов для расчёта только возвышения.');const required=[0,0,2,3,3,4,4,5,5,6,6][t];if(t>f&&required>end)return fail('Для таланта '+t+' требуется фаза возвышения '+required+'. Увеличь целевой уровень или отметь возвышение на пороге.');for(const [br,bn,cr,cn,boss,crown,mora] of UP.talent.slice(f-1,t-1)){add(entry.books[br-2],bn);add(entry.common[cr-1],cn);add(entry.boss,boss);add('crown_of_insight',crown);add('mora',mora);}}}
const pairs=Object.entries(calculatedMaterials).sort((a,b)=>a[0]==='mora'?-1:b[0]==='mora'?1:0);for(const [k,n] of pairs){const v=lookupItem(k),card=document.createElement('div');card.className='material-card';card.append(itemLabel(v,k,'',v?.r));const count=document.createElement('b');count.className='material-quantity';count.textContent=fmt(n);card.append(count);out.append(card);}if(!pairs.length)out.textContent='Для выбранной цели дополнительные материалы не нужны.';warning.textContent=messages.join(' ');$('#upSummary').textContent=pairs.length+' видов ресурсов';$('#upAdd').disabled=!pairs.length;$('#upCopy').disabled=!pairs.length;}
function initUpgrade(){$$('[data-up-kind]').forEach(b=>b.onclick=()=>changeUpgradeKind(b.dataset.upKind));$('#upSearch').addEventListener('input',()=>{upgradeLimit=30;renderUpgradeMatches();});$('#upRarity').addEventListener('change',()=>{upgradeLimit=30;renderUpgradeMatches();});$('#upMore').onclick=()=>{upgradeLimit+=30;renderUpgradeMatches();};$$('[data-step]').forEach(b=>b.onclick=()=>{const [id,delta]=b.dataset.step.split(':');const el=$('#'+id);el.value=String(Math.max(1,Math.min(90,num(el.value)+Number(delta))));calcUpgrade();});$$('[data-up-preset]').forEach(b=>b.onclick=()=>{const [f,t]=b.dataset.upPreset.split(':');$('#upFrom').value=f;$('#upTo').value=t;$('#upFromAsc').checked=false;$('#upToAsc').checked=false;calcUpgrade();});$$('[data-tal-preset]').forEach(b=>b.onclick=()=>{for(let n=0;n<3;n++){const f=num($('#talFrom'+n).value);$('#talTo'+n).value=String(b.dataset.talPreset==='same'?f:Math.max(f,Number(b.dataset.talPreset)));}calcUpgrade();});for(const id of ['upItem','upFrom','upTo','upFromAsc','upToAsc','talFrom0','talFrom1','talFrom2','talTo0','talTo1','talTo2'])$('#'+id).addEventListener('input',calcUpgrade);$('#upAdd').onclick=()=>{if(!Object.keys(calculatedMaterials).length)return;for(const [id,n] of Object.entries(calculatedMaterials)){const name=lookupItem(id)?.n||id;const existing=state.resources.find(r=>r.itemId===id||normalize(r.name)===normalize(name));if(existing)existing.need=num(existing.need)+n;else state.resources.push({name,itemId:id,need:n,have:0});}save();renderResources();notice('Материалы добавлены в общий план. Повторное добавление суммирует цели.');navigate('resources');};$('#upCopy').onclick=async()=>{const str=Object.entries(calculatedMaterials).map(([id,n])=>(lookupItem(id)?.n||id)+': '+fmt(n)).join('\n');try{await navigator.clipboard.writeText(str);notice('Список скопирован.');}catch{notice('Не удалось скопировать список.');}};$('#mapEmbed').onclick=()=>{const wrap=$('#mapFrame');if(wrap.firstChild)return;const f=document.createElement('iframe');f.src='https://genshin-impact-map.appsample.com/ru/';f.title='Интерактивная карта Тейвата';f.referrerPolicy='no-referrer';f.loading='lazy';wrap.append(f);};fillUpgrade();}

let deferredPrompt=null;window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredPrompt=e;$('#installBtn').hidden=false;});$('#installBtn').onclick=async()=>{if(!deferredPrompt)return;deferredPrompt.prompt();await deferredPrompt.userChoice;deferredPrompt=null;$('#installBtn').hidden=true;};if('serviceWorker'in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).catch(()=>{});migrateGameNames();initCatalog();initUpgrade();initDashboard();initHistory();render();
